type IconComponent = typeof IconStar;
type NonEmptyIconPool = readonly [IconComponent, ...IconComponent[]];

const OUTLINED: NonEmptyIconPool = [
	IconStar,
	IconHeart,
	IconPlus,
	IconArrowRight,
	IconDownload,
	IconSettings,
	IconTrash,
	IconBolt,
	IconBell,
	IconBookmark,
	IconCamera,
	IconClock,
	IconCloud,
	IconFlag,
	IconFolder,
	IconHome,
	IconMail,
	IconMapPin,
	IconMoon,
	IconSun,
	IconRocket,
	IconSparkles,
	IconThumbUp,
];

const FILLED: NonEmptyIconPool = [
	IconStarFilled,
	IconHeartFilled,
	IconBellFilled,
	IconBookmarkFilled,
	IconBoltFilled,
	IconCircleCheckFilled,
	IconTrashFilled,
	IconSettingsFilled,
	IconPlayerPlayFilled,
	IconFlagFilled,
	IconFolderFilled,
	IconHomeFilled,
	IconMoonFilled,
	IconSunFilled,
