        <PromptVersionsView
          versions={PROMPT_VERSIONS.filter((v) => v.agentName === agent.name)}
          loading={false}
          skeleton={false}
          renderProse={(v) => (
            <PromptProseView template={v.template} slots={SLOT_EXAMPLES[v.id]} />
          )}
        />
      </section>

      {/* Traces table — click a row to open its drawer. */}
      <div className="flex flex-col gap-3 mt-4">
        <div className="flex flex-col gap-3">
          <TooltipProvider delay={150}>
            <Table className="table-fixed">
              <TableHeader>
                <TableRow>
                  <TableHead>Trace</TableHead>
                  <TableHead className="w-44">Workflow</TableHead>
                  <SortableHead
                    sortKey="spans"
                    sort={sort}
                    onSort={toggle}
                    align="right"
                    className="w-20"
                  >
                    Spans
                  </SortableHead>
                  <SortableHead
                    sortKey="duration"
                    sort={sort}
                    onSort={toggle}
                    align="right"
                    className="w-28"
                  >
                    Duration
                  </SortableHead>
                  <SortableHead
                    sortKey="cost"
                    sort={sort}
                    onSort={toggle}
                    align="right"
                    className="w-28"
                  >
                    Cost
                  </SortableHead>
                  <SortableHead
                    sortKey="when"
                    sort={sort}
                    onSort={toggle}
                    align="right"
                    className="w-32"
                  >
                    When
                  </SortableHead>
                </TableRow>
              </TableHeader>
