				/>
				<StatCard
					icon={IconCoinFilled}
					iconClassName="text-amber-400 dark:text-yellow-500"
					label={KPIS[1]!.label}
					size="sm"
					value={KPIS[1]!.value}
					delta={KPIS[1]!.delta}
					deltaInverted
					hint={KPIS[1]!.hint}
					chart={
						<CardSparkline
							data={OVERVIEW_SERIES.map((d) => d.cost)}
							className="text-yellow-400/50 dark:text-yellow-500/35"
						/>
					}
				/>
				<StatCard
					icon={IconGaugeFilled}
					iconClassName="text-fuchsia-400 dark:text-fuchsia-500"
					label={KPIS[2]!.label}
					size="sm"
					value={KPIS[2]!.value}
					delta={KPIS[2]!.delta}
					hint={KPIS[2]!.hint}
					chart={
