								tickFormatter={(v) => formatDuration(Number(v))}
							/>
							<AreaChart.Tooltip
								labelFormatter={(v) => formatBucketFull(String(v))}
								valueFormatter={(_v, key, row) =>
									formatDuration(Number(row[`${key}Abs`] ?? _v))
