					</ToggleChip>
					<ClearFiltersButton
						show={!!(search || agentFilter || customerFilter || errorsOnly)}
						onClick={() => {
							setSearch("");
							setAgentFilter("");
							setCustomerFilter("");
							setErrorsOnly(false);
						}}
					/>
					<div className="ml-auto">
						<DemoRange />
					</div>
				</Toolbar>

				<div className="flex flex-col -mt-2">
					<TooltipProvider delay={150}>
						<Table className="table-fixed min-w-240">
							<TableHeader>
								<TableRow>
									<TableHead>Session</TableHead>
									<SortableHead
										sortKey="turns"
										sort={sort}
										onSort={toggle}
										align="right"
										className="w-27"
									>
										Turns
									</SortableHead>
									<SortableHead
										sortKey="tokens"
										sort={sort}
										onSort={toggle}
										align="right"
										className="w-29"
									>
										Tokens
									</SortableHead>
									<SortableHead
										sortKey="cost"
										sort={sort}
										onSort={toggle}
										align="right"
										className="w-32"
									>
										Cost
									</SortableHead>
									<SortableHead
										sortKey="last"
										sort={sort}
										onSort={toggle}
										align="right"
										className="w-36"
									>
										Last activity
									</SortableHead>
								</TableRow>
							</TableHeader>
							<TableBody>
								{rows.map((s) => (
									<TableRow
										key={s.sessionId}
										interactive
										onClick={() => openDetail({ type: "session", id: s.sessionId })}
									>
										<TableCell className="h-16">
											<div className="flex flex-col gap-1">
												<div className="flex items-center gap-2">
													<span className="truncate font-normal text-[14px]">
