  version,
  agentName,
  className,
}: {
  version: { id: string; number: number } | null | undefined;
  agentName: string | null | undefined;
  className?: string;
}) {
  if (!version) return null;
  const label = `v${version.number}`;
  const classes = cn("font-mono normal-case tabular-nums", className);
